// Writes src/resources.generated.ts from the locales/ folder. Do not edit the output by hand.
import { readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const localesDir = join(root, 'locales');
const locales = readdirSync(localesDir)
  .filter((d) => !d.startsWith('.'))
  .sort();
const namespaces = readdirSync(join(localesDir, 'en'))
  .filter((f) => f.endsWith('.json'))
  .map((f) => f.slice(0, -5))
  .sort();

const id = (l, ns) => `${l}_${ns}`.replace(/[^a-zA-Z0-9_]/g, '_');
const lines = [
  '// Generated by scripts/generate.mjs from locales/. Do not edit.',
  ...locales.flatMap((l) =>
    namespaces.map(
      (ns) => `import ${id(l, ns)} from '../locales/${l}/${ns}.json' with { type: 'json' };`,
    ),
  ),
  '',
  `export const NAMESPACES = ${JSON.stringify(namespaces)} as const;`,
  '',
  'export const resources = {',
  ...locales.map(
    (l) =>
      `  ${JSON.stringify(l)}: { ${namespaces.map((ns) => `${ns}: ${id(l, ns)}`).join(', ')} },`,
  ),
  '} as const;',
  '',
];
writeFileSync(join(root, 'src', 'resources.generated.ts'), lines.join('\n'));
